        {
          "proposicao": "O trecho apresenta fator humano como estudo das capacidades e limitações humanas no trabalho, incluindo interações entre pessoas, máquinas e equipamentos, procedimentos escritos e verbais, regras, condições ambientais e outras pessoas.",
          "trechos": [
            "E819c96da71f80877:697:1395"
          ],
          "condicoes": [
            "Na definição conceitual reproduzida pela fonte"
          ],
          "limites": [
            "A fonte tem independência documental indeterminada e compila referências, o que limita rastreabilidade e força probatória",
            "O trecho é conceitual e não trata especificamente de contratadas, supervisão ou FPSO"
          ]
        },
        {
          "proposicao": "O texto sustenta que erros humanos não se restringem à operação, podendo ocorrer também em projeto, manufatura, manutenção e administração, e que podem ser favorecidos por situações que os propiciam, como características perigosas em produtos.",
          "trechos": [
